css:
.e3-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #04060f; }
.e3-home { position: absolute; right: 14px; top: 12px; font-size: 19px !important; padding: 8px 14px !important; }
.e3-lab { font-size: 17px; padding: 2px 10px; }
.e3-gauge { position: absolute; left: 14px; bottom: 14px; display: grid; gap: 2px; min-width: 150px; padding: 10px 14px; border-radius: 12px; background: rgba(10,14,32,.82); border: 2px solid #5a6a90; color: #fbfcf9; font: 600 17px/1.35 var(--f-body); pointer-events: none; }
.e3-gauge b { font: 800 26px/1.2 var(--f-body); color: #ffd84d; }
.e3-g-lay { font-weight: 800; color: var(--c); display: inline-block; transform-origin: left center; }
.e3-g-st.liq { color: #ffb347; font-weight: 800; }
.e3-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.e3-table { width: 100%; border-collapse: collapse; font-size: 19px; }
.e3-table th, .e3-table td { border: 1.5px solid var(--rule); padding: 4px 8px; text-align: left; }
.e3-table thead th, .e3-table tbody th { background: color-mix(in srgb, var(--accent) 12%, #fff); white-space: nowrap; }

